Dataspatium.assets.register("presets/api/skogsstyrelsen-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"skogsstyrelsen-geodata\",\n  \"name\": \"Skogsstyrelsen geodata (ArcGIS)\",\n  \"publisher\": \"Skogsstyrelsen\",\n  \"description\": \"Skogliga geodata från Skogsstyrelsen: nyckelbiotoper, avverkningsanmälningar, naturvärden med mera. Välj tjänst och lager och hämta objekten; begränsa med ett område.\",\n  \"docs\": \"https://www.skogsstyrelsen.se/sjalvservice/karttjanster/geodatatjanster/\",\n  \"license\": {\n    \"name\": \"Skogsstyrelsens öppna data\",\n    \"url\": \"https://www.skogsstyrelsen.se/sjalvservice/karttjanster/geodatatjanster/\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://geodpags.skogsstyrelsen.se/arcgis/rest/services\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"arcgis\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Swedish Forest Agency geodata (ArcGIS)\",\n      \"description\": \"Forestry geodata: key habitats, felling notifications, natural values and more. Choose a service and layer and fetch the features; limit by an area.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"Skogsstyrelsen geodata (ArcGIS)\",\n      \"description\": \"Skovlige geodata fra Skogsstyrelsen: nøglebiotoper, fældningsanmeldelser, naturværdier med mere. Vælg tjeneste og lag og hent objekterne; begræns med et område.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"Skogsstyrelsen geodata (ArcGIS)\",\n      \"description\": \"Skoglige geodata fra Skogsstyrelsen: nøkkelbiotoper, hogstmeldinger, naturverdier med mer. Velg tjeneste og lag og hent objektene; begrens med et område.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"Skogsstyrelsen paikkatieto (ArcGIS)\",\n      \"description\": \"Metsäpaikkatietoa Skogsstyrelseniltä: avainbiotoopit, hakkuuilmoitukset, luontoarvot ja muuta. Valitse palvelu ja taso ja nouda kohteet; rajaa alueella.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Landupplýsingar Skogsstyrelsen (ArcGIS)\",\n      \"description\": \"Skógarlandupplýsingar frá Skogsstyrelsen: lykilbúsvæði, tilkynningar um skógarhögg, náttúruverðmæti og fleira. Veldu þjónustu og lag og sæktu fitjurnar; takmarkaðu við svæði.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
